import json
from pathlib import Path
A, A2, ST, T, F = "author", "author2", "study", "trylog", "ai"
def sc(art, head, cap, nar, cues, src=None, sfx=(), **kw):
    for w in cues: assert w in nar, (w, nar)
    return {"art": art, "src": src, "head": head, "caption": cap, "narration": nar, "cues": {f"c{i+1}": w for i, w in enumerate(cues)}, "sfx": [[f"c{i}", k] for i, k in sfx], **kw}
def save(folder, title, tag, note, badges, thumb, scenes):
    for i, s in enumerate(scenes, 1):
        s["id"] = f"s{i:02d}"
        if s["src"] is None: del s["src"]
    tl = {"title": title, "tag": tag, "note": note, "size": [1920, 1080], "suffix": "", "speed": 1.45, "lead": 0.2, "tail": 0.28,
          "voice": "本人の声（Fish Audio・参照音声からの合成）", "thumb": thumb, "badges": badges, "scenes": scenes}
    Path(folder, "timeline.json").write_text(json.dumps(tl, ensure_ascii=False, indent=1) + "\n")
    print(folder, len(scenes), sum(len(s["narration"]) for s in scenes))
R, F, T = "real", "ai", "trylog"
B = {"real": "本人の実例（本人の文章より）", "ai": "AI生成・架空の人物", "trylog": "TRY LOGの提案"}

